// Get form data
const data = $json;

// Clean text safely
const cleanText = (value) => {
  if (value === undefined || value === null) return '';
  return String(value).trim().replace(/\s+/g, ' ');
};

// Clean email
const email = cleanText(data['Email Address']).toLowerCase();

// Clean phone number
let phone = cleanText(data['Phone Number']);

// Remove spaces, brackets, hyphens, dots, etc.
phone = phone.replace(/[^\d+]/g, '');

// Make Indian numbers consistent
if (phone.startsWith('0')) {
  phone = '+91' + phone.substring(1);
} else if (phone.startsWith('91') && !phone.startsWith('+91')) {
  phone = '+' + phone;
} else if (/^\d{10}$/.test(phone)) {
  phone = '+91' + phone;
}

// Clean other fields
const fullName = cleanText(data['Full Name']);
const companyName = cleanText(data['Company Name']);
const jobTitle = cleanText(data['Job Title/Role']);
const companySize = cleanText(data['Company size']);
const serviceRequired = cleanText(data['Service Required']);
const timeline = cleanText(data['Timeline']);

// Convert budget to number
let budget = data['Estimated budget'];

if (budget === undefined || budget === null || budget === '') {
  budget = 0;
} else {
  budget = Number(String(budget).replace(/[^\d.]/g, ''));
}

if (isNaN(budget)) {
  budget = 0;
}

// Return cleaned data
return {
  json: {
    full_name: fullName,
    email: email,
    phone: phone,
    company_name: companyName,
    job_title: jobTitle,
    company_size: companySize,
    service_required: serviceRequired,
    estimated_budget: budget,
    timeline: timeline,
    submitted_at: data['submittedAt'] || new Date().toISOString()
  }
};

