// Get the AI output
const aiOutput = $json.output;

// Remove markdown code fences if the AI adds them
const cleanedOutput = String(aiOutput)
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

// Parse AI JSON
let result;

try {
  result = JSON.parse(cleanedOutput);
} catch (error) {
  throw new Error(
    'AI output is not valid JSON. Raw output: ' + aiOutput
  );
}

// Get original cleaned lead data
const lead = $('cleaning data').first().json;

// Return complete lead + AI qualification data
return [
  {
    json: {

      // ===== LEAD DETAILS =====
      full_name: lead.full_name || '',
      email: lead.email || '',
      phone: lead.phone || '',
      company_name: lead.company_name || '',
      job_title: lead.job_title || '',
      company_size: lead.company_size || '',
      service_required: lead.service_required || '',
      estimated_budget: lead.estimated_budget || 0,
      timeline: lead.timeline || '',
      submitted_at: lead.submitted_at || '',

